INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 3, 'theory', 'Quiz: VT-x, AMD-V, VM exit, ARM EL2, and RISC-V H');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 0, 'What are the root and non-root modes in VT-x?', '["Monitor mode and guest mode, each with its own four protection rings", "Privileged and ordinary users of the guest OS", "Two operating modes of the processor cache", "The host and guest file systems"]', 0, 'The guest kernel runs in ring 0 of non-root mode and executes privileged instructions as usual, but the monitor in root mode decides when the guest must hand control back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 1, 'What is stored in the VMCS?', '["The guest''s disk image", "The host''s page tables", "Guest and host state, the intercept control bits, and the reason for the last exit", "The list of the guest''s network interfaces"]', 2, 'The VMCS is a page of memory accessible only through the VMREAD and VMWRITE instructions. On AMD the same role is played by the VMCB, and the guest is started by the VMRUN instruction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 2, 'Which of these events always causes an exit from the guest, with no configuration?', '["Adding two numbers", "Writing to general-purpose registers", "Accessing the guest''s own memory", "Executing the CPUID instruction"]', 3, 'CPUID, the VMCALL hypercall, and the virtualization instructions themselves always exit. I/O ports, HLT, and accesses to CR3 and MSRs are configured with VMCS bits.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 3, 'At which ARM exception level does the hypervisor run?', '["EL3", "EL2", "EL1", "EL0"]', 1, 'The guest kernel runs at EL1, programs at EL0, and the hypervisor at the more privileged EL2. The HVC instruction takes you from EL1 to EL2. EL3 is the secure monitor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 3, 4, 'Why are address space tags (VPID on Intel, ASID on AMD) needed?', '["They encrypt the guest''s memory from the host", "They set the priority of the virtual machine", "They avoid a full flush of the translation cache on every switch between the guest and the monitor", "They number the physical processor cores"]', 2, 'Translation cache entries are tagged with their owner, so entry and exit don''t have to throw all of them away: an exit becomes cheaper.');
